const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Mount Vesuvius coordinates (approximate center of the cone)
  const vesuvius = ee.Geometry.Point(14.426, 40.822);
  // Define a small buffer around the point to represent the cone area
  const coneArea = vesuvius.buffer(500); // 500 meters radius

  const startDate = '2022-01-02';
  const endDate = '2022-01-03'; // Include the full day

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(coneArea)
    .filterDate(startDate, endDate);

  // Check if any images are found for the specified date and location
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Landsat 8 images found for Mount Vesuvius on January 2, 2022.");
    console.log("C1");
    return;
  }

  console.log(`Initial images found: ${collectionSize}`);

  // Get the first image from the collection (Landsat has 16-day revisit, so likely one or none)
  const image = ee.Image(collection.first());

  // Landsat 8 Cloud Masking Function (QA_PIXEL band)
  // Based on GEE documentation for Landsat Level-2 QA_PIXEL band
  function maskL8Clouds(image) {
    const qaPixel = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    // Bit 3: Cloud Shadow (1 = Yes, 0 = No)
    // Bit 5: Clouds (1 = Yes, 0 = No)
    // Bit 7: Cirrus (1 = Yes, 0 = No) - Not strictly needed for "visible", but good for clarity.
    // Bit 9: Snow/Ice (1 = Yes, 0 = No)
    // Bit 10: Cloud Confidence (00 = Not Set, 01 = Low, 10 = Medium, 11 = High)
    // Bit 11: Cloud Confidence (second bit)
    // Let's mask for cloud shadow (bit 3), clouds (bit 5), and optionally cirrus (bit 7).
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    const cirrusBitMask = (1 << 7); // For more robust cloud detection

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qaPixel.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qaPixel.bitwiseAnd(cloudsBitMask).eq(0))
                   .and(qaPixel.bitwiseAnd(cirrusBitMask).eq(0)); // Also mask cirrus

    return image.updateMask(mask);
  }

  // Apply the cloud mask
  const maskedImage = maskL8Clouds(image);

  // 3. Processing & 4. Calculation
  // Count the number of valid (unmasked) pixels within the cone area.
  // We'll use the 'SR_B4' (Red band) as a representative band for pixel counting.
  const validPixelsReducer = maskedImage.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: coneArea,
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  });

  const validPixelCount = await validPixelsReducer.get('SR_B4').getInfo();

  // 5. Validation & Final Answer
  if (validPixelCount === null) {
    console.log("Calculation of valid pixels returned null.");
    console.log("C3");
    return;
  }

  console.log(`Valid pixels over Vesuvius cone after cloud masking: ${validPixelCount}`);

  if (validPixelCount > 0) {
    console.log("A"); // Yes, Vesuvius was visible.
  } else {
    console.log("B"); // No, Vesuvius was not visible (likely due to clouds).
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
